import requests

# Run this in command line "python manage.py validate_cert_test.py
# base64 cert
cert = ""
url = ""  # Enter url here for cert validation view
print(f"Certificate (base64) length: {len(cert)}")
print(f"First 80 chars: {cert[:80]}\n")

# Send as base64 in header
headers = {
    'X-Client-Certificate': cert
}

print(f"Headers being sent: {list(headers.keys())}\n")

# Test
print("=" * 60)
print("Sending Certificate")
print("=" * 60)

try:
    response = requests.get(
        url,
        headers=headers
    )
    print(f"Status: {response.status_code}")
    print(f"Response: {response.json()}")
except Exception as e:
    print(f"Error: {e}")
